mapper.select:
SELECT AA.* , COUNT(*) OVER() AS TOTAL_CNT FROM ( SELECT TBI.CARRYIN_DATE
,COUNT(TBI.IN_NO) AS TOTAL_IN_CNT ,SUM(TBI.CT) AS TOTAL_IN_SUM_CT ,SUM(TBI.WT) AS TOTAL_IN_SUM_WT FROM TB_BMS_IN TBI WITH (NOLOCK) LEFT JOIN TB_BMS_OUT TBO WITH (NOLOCK) ON TBO.IN_NO = TBI.IN_NO WHERE TBI.CARRYIN_DATE >= #{srchStartDate} AND TBI.CARRYIN_DATE <= #{srchEndDate}
AND 1 = 0
GROUP BY TBI.CARRYIN_DATE
) AA

SELECT AA.* , COUNT(*) OVER() AS TOTAL_CNT FROM ( SELECT TBO.CARRYOUT_DATE
,COUNT(TBO.OUT_NO) AS TOTAL_OUT_CNT ,SUM(TBO.OUT_CT) AS TOTAL_OUT_SUM_CT ,SUM(TBO.OUT_WT) AS TOTAL_OUT_SUM_WT FROM TB_BMS_OUT TBO WITH (NOLOCK) LEFT JOIN TB_BMS_IN TBI WITH (NOLOCK) ON TBI.IN_NO = TBO.IN_NO WHERE TBO.CARRYOUT_DATE >= #{srchStartDate} AND TBO.CARRYOUT_DATE <= #{srchEndDate}
AND 1 = 0
GROUP BY TBO.CARRYOUT_DATE
) AA
